import{_ as l,H as t,f as n,b as e,j as r}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"Q71 | 投资回报：AI模型带来的业务价值","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q71｜投资回报：AI模型带来的业务价值.md","filePath":"致程序员：AI百问百答/Q71｜投资回报：AI模型带来的业务价值.md","lastUpdated":1795559851000}'),I={name:"致程序员：AI百问百答/Q71｜投资回报：AI模型带来的业务价值.md"};function _(p,a,s,o,A,d){return t(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"q71-投资回报-ai模型带来的业务价值",tabindex:"-1"},[r("Q71 | 投资回报：AI模型带来的业务价值 "),e("a",{class:"header-anchor",href:"#q71-投资回报-ai模型带来的业务价值","aria-label":'Permalink to "Q71 | 投资回报：AI模型带来的业务价值"'},"​")],-1),e("ul",null,[e("li",null,"作者介绍：Tyler，前亚马逊应用科学家，头部大厂 AIGC 算法技术负责人")],-1),e("p",null,"Q：如何量化 AI 模型带来的业务价值？是否有明确的 ROI（投资回报率）评估机制？",-1),e("p",null,"Tyler：可以通过 ROI 来评价 AI 模型带来的业务价值，但现实中一个常见误区是过于依赖短期指标进行优化，例如点击率提升、人工成本下降等。这些指标虽然易于度量和汇报，但正如古德哈特定律所警示：“一旦指标成为目标，它就不再是一个好指标。” 过度追逐短期 ROI，往往会导致系统“过拟合指标”，进而牺牲用户体验、削弱品牌信任，甚至阻碍产品结构的长期演进。",-1),e("p",null,"我曾在《AI 大模型系统实战》的第 31 节课中举过微软投资 OpenAI 的例子。微软要收回这笔庞大投资，需进一步商品化 OpenAI，建立商业壁垒创造超额利润。这就要求 OpenAI 从早期愿景驱动转向以用户需求为牵引的商业化发展，完成 增加用户规模、提高用户使用时长、提升付费用户转化率这三大任务。",-1),e("p",null,"前两个任务的关键在于让技术使用户在使用产品时更便捷、更省力，如大模型技术处理多种信息格式，吸引用户使用 ChatGPT，进而提升用户生命周期价值（LTV）和业务营收利润。",-1),e("p",null,"了解了这一逻辑后，我们可以理解为什么 GPT 的下一个发展方向是多模态领域。这也解释了为什么 OpenAI 没有急于推出 GPT-5，而是首先推出了 GPT-4V。",-1),e("p",null,"说回 AI 投入评估回报的问题，我认为 AI 模型带来业务价值的提升并非一蹴而就，需在短期收益与长期价值间找到平衡。在设计评估机制时，我们不仅要关注短期效率提升，还要将 LTV与品牌资产的长期积累纳入考量，构建更具战略视角的 ROI 机制。",-1)])])}const u=l(I,[["render",_]]);export{c as __pageData,u as default};
